import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();
        int n = sc.nextInt();

        int g = gcd(x, y);
        x /= g;
        y /= g;

        long xx = 0, ans_xx = 0;
        long ans_yy = 1;

        double d = 1.0;
        double eps = 1e-10;

        for (long yy = 1; yy <= n; yy++) {
            while (Math.abs(d * x / y - d * xx / yy) > Math.abs(d * x / y - d * (xx + 10000) / yy)) {
                xx += 10000;
            }
            while (Math.abs(d * x / y - d * xx / yy) + eps > Math.abs(d * x / y - d * (xx + 1) / yy)) {
                xx++;
            }
            if (Math.abs(d * x / y - d * xx / yy) < Math.abs(d * x / y - d * ans_xx / ans_yy)) {
                ans_xx = xx;
                ans_yy = yy;
            }
        }

        long resultNumerator = Math.max(0L, ans_xx - (y == 2 && ans_xx != x ? 1 : 0));
        System.out.println(resultNumerator + "/" + ans_yy);
        sc.close();
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
